import './App.css';
import { invoke } from '@forge/bridge';
import { useEffect, useState } from 'react';

const PARALLEL_LOGO = 'data:image/png;base64,';

function App() {
    const [projects, setProjects] = useState([]);
    const [selectedProject, setSelectedProject] = useState(null);
    const [search, setSearch] = useState('');
    const [activeNav, setActiveNav] = useState('Overview');
    const [projectsLoading, setProjectsLoading] = useState(true);
    const [projectsError, setProjectsError] = useState('');
    const [projectReloadKey, setProjectReloadKey] = useState(0);
    const [issueState, setIssueState] = useState({ projectKey: null, loading: false, error: '', issues: [] });
    const [issueReloadKey, setIssueReloadKey] = useState(0);
    const selectedProjectKey = selectedProject ? selectedProject.key : null;

    useEffect(() => {
        let current = true;
        setProjectsLoading(true);
        setProjectsError('');

        invoke('getJiraProjects')
            .then((result) => {
                if (!current) return;
                if (!result?.success || !Array.isArray(result.projects)) {
                    setProjects([]);
                    setProjectsError(result?.message || 'Unable to load Jira projects.');
                    return;
                }
                setProjects(result.projects);
            })
            .catch(() => {
                if (!current) return;
                setProjects([]);
                setProjectsError('Unable to load Jira projects. Please try again.');
            })
            .finally(() => {
                if (current) setProjectsLoading(false);
            });

        return () => { current = false; };
    }, [projectReloadKey]);

    useEffect(() => {
        if (!selectedProjectKey) {
            setIssueState({ projectKey: null, loading: false, error: '', issues: [] });
            return undefined;
        }

        let current = true;
        const projectKey = selectedProjectKey;
        setIssueState({ projectKey, loading: true, error: '', issues: [] });

        invoke('getJiraIssues', { projectKey })
            .then((result) => {
                if (!current) return;
                if (!result?.success || !Array.isArray(result.issues)) {
                    setIssueState({
                        projectKey,
                        loading: false,
                        error: result?.message || `Unable to load issues for ${projectKey}.`,
                        issues: [],
                    });
                    return;
                }
                setIssueState({ projectKey, loading: false, error: '', issues: result.issues });
            })
            .catch(() => {
                if (!current) return;
                setIssueState({ projectKey, loading: false, error: `Unable to load issues for ${projectKey}. Please try again.`, issues: [] });
            });

        return () => { current = false; };
    }, [selectedProjectKey, issueReloadKey]);

    const filteredProjects = projects.filter((project) => {
        const query = search.trim().toLowerCase();
        return (
            (project.name || '').toLowerCase().includes(query) ||
            (project.key || '').toLowerCase().includes(query)
        );
    });
    const currentIssueState = selectedProjectKey && issueState.projectKey === selectedProjectKey
        ? issueState
        : { projectKey: selectedProjectKey, loading: Boolean(selectedProjectKey), error: '', issues: [] };

    function showOverview() {
        setSelectedProject(null);
        setActiveNav('Overview');
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    function showProjects() {
        setSelectedProject(null);
        setActiveNav('Projects');
        window.setTimeout(() => {
            document.getElementById('projects')?.scrollIntoView({ behavior: 'smooth' });
            document.getElementById('project-search')?.focus({ preventScroll: true });
        }, 0);
    }

    function showSimulations() {
        if (!selectedProject) {
            if (!projects.length) {
                showProjects();
                return;
            }
            setSelectedProject(projects[0]);
        }
        setActiveNav('Simulations');
        window.setTimeout(() => {
            document.getElementById('project-simulations')?.scrollIntoView({ behavior: 'smooth' });
        }, 0);
    }

    return (
        <div className="app">
            <aside className="sidebar">
                <a className="logo" href="#overview" onClick={(event) => { event.preventDefault(); showOverview(); }} aria-label="PARALLEL overview">
                    <img src={PARALLEL_LOGO} alt="PARALLEL" />
                </a>

                <p className="menu-label">WORKSPACE</p>

                <nav className="workspace-nav" aria-label="Workspace navigation">
                    <button type="button" className={activeNav === 'Overview' ? 'active' : ''} onClick={showOverview}>Overview</button>
                    <button type="button" className={activeNav === 'Projects' ? 'active' : ''} onClick={showProjects}>Projects</button>
                    <button type="button" className={activeNav === 'Simulations' ? 'active' : ''} onClick={showSimulations}>Simulations</button>
                </nav>

                <div className="sidebar-note">
                    <span className="note-mark" aria-hidden="true">✳</span>
                    <p>Make room for a different perspective.</p>
                </div>
            </aside>

            <main className="main-content" id="overview">
                <header className="topbar">
                    <div className="breadcrumb">Workspace <span>/</span> {selectedProject ? selectedProject.name : 'Overview'}</div>
                    {selectedProject && <button type="button" className="breadcrumb-back" onClick={showProjects}>All projects</button>}
                </header>

                {selectedProject ? (
                    <section className="project-workspace" aria-labelledby="workspace-title">
                        <button type="button" className="back-button" onClick={showProjects}>← <span>Back to Projects</span></button>

                        <div className="workspace-heading">
                            <div className="project-monogram" aria-hidden="true">{selectedProject.key.slice(0, 1)}</div>
                            <div>
                                <p className="eyebrow">PROJECT WORKSPACE · {selectedProject.key}</p>
                                <h1 id="workspace-title">{selectedProject.name}</h1>
                                <p className="workspace-description">Jira project {selectedProject.key}</p>
                            </div>
                        </div>

                        <div className="project-details">
                            <article className="detail-card"><span>Jira project key</span><strong>{selectedProject.key}</strong></article>
                            <article className="detail-card"><span>Issues returned (up to 50)</span><strong>{currentIssueState.loading ? 'Loading…' : currentIssueState.error ? '—' : currentIssueState.issues.length}</strong></article>
                        </div>

                        <section className="recent-section" id="project-simulations" aria-labelledby="simulations-title">
                            <div className="section-heading">
                                <div>
                                    <p className="eyebrow">PROJECT WORKSPACE</p>
                                    <h2 id="simulations-title">Jira Issues</h2>
                                    <p>Most recent issues for {selectedProject.key}, up to 50.</p>
                                </div>
                            </div>
                            {currentIssueState.loading ? (
                                <div className="jira-state" role="status"><span className="loading-indicator" /> Loading issues for {selectedProject.key}…</div>
                            ) : currentIssueState.error ? (
                                <div className="jira-state jira-error" role="alert"><span>{currentIssueState.error}</span><button type="button" className="retry-button" onClick={() => setIssueReloadKey((key) => key + 1)}>Try again</button></div>
                            ) : currentIssueState.issues.length === 0 ? (
                                <div className="jira-state" role="status">No Jira issues were returned for this project.</div>
                            ) : (
                                <div className="jira-issue-list" aria-label={`Jira issues for ${selectedProject.key}`}>
                                    {currentIssueState.issues.map((issue) => (
                                        <article className="jira-issue" key={issue.id || issue.key}>
                                            <div className="jira-issue-main">
                                                <div className="jira-issue-meta"><strong>{issue.key}</strong><span>{issue.issueType || 'Issue'}</span></div>
                                                <h3>{issue.summary || 'Untitled issue'}</h3>
                                                <p>{issue.assignee ? `Assigned to ${issue.assignee}` : 'Unassigned'}{issue.priority ? ` · ${issue.priority} priority` : ''}</p>
                                            </div>
                                            <span className="jira-issue-status">{issue.status || 'No status'}</span>
                                        </article>
                                    ))}
                                </div>
                            )}
                        </section>
                    </section>
                ) : (
                    <>
                        <section className="hero" aria-labelledby="hero-title">
                            <div className="hero-copy">
                                <p className="eyebrow">A NEW WAY TO SEE WHAT’S NEXT</p>
                                <h1 id="hero-title">Explore more<br /><span>possibilities.</span></h1>
                                <p className="hero-description">Every decision opens a different path. Bring your projects into view and explore what could happen next.</p>
                                <button type="button" className="primary-button" onClick={showProjects}>Choose a Jira Project <span aria-hidden="true">→</span></button>
                            </div>

                            <div className="futures-art" role="img" aria-label="Two open portals showing different possible futures">
                                <svg viewBox="0 0 520 360" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false">
                                    <defs>
                                        <linearGradient id="futureLeft" x1="0" y1="0" x2="0.9" y2="1"><stop stopColor="#d9e8ff"/><stop offset=".48" stopColor="#9bbcf1"/><stop offset="1" stopColor="#727fd1"/></linearGradient>
                                        <linearGradient id="futureRight" x1="0" y1="0" x2=".9" y2="1"><stop stopColor="#f5e7ff"/><stop offset=".5" stopColor="#d9c0f2"/><stop offset="1" stopColor="#9b83d1"/></linearGradient>
                                        <linearGradient id="frame" x1="0" y1="0" x2="1" y2="1"><stop stopColor="#fff"/><stop offset=".45" stopColor="#b5a1ee"/><stop offset="1" stopColor="#7558c3"/></linearGradient>
                                        <linearGradient id="water" x1="0" y1="0" x2="0" y2="1"><stop stopColor="#d6e2ff" stopOpacity=".7"/><stop offset="1" stopColor="#7a86cd" stopOpacity=".95"/></linearGradient>
                                        <clipPath id="leftPortal"><path d="M111 53 229 91v206l-118 25z"/></clipPath>
                                        <clipPath id="rightPortal"><path d="m309 91 118-38v269l-118-25z"/></clipPath>
                                        <filter id="portalShadow" x="-35%" y="-25%" width="170%" height="170%"><feGaussianBlur stdDeviation="13"/></filter>
                                    </defs>
                                    <ellipse cx="265" cy="314" rx="175" ry="22" fill="#7963b8" opacity=".16" filter="url(#portalShadow)"/>
                                    <ellipse cx="264" cy="177" rx="239" ry="57" fill="none" stroke="#fff" strokeOpacity=".82" strokeWidth="2" transform="rotate(-8 264 177)"/>
                                    <ellipse cx="264" cy="183" rx="234" ry="83" fill="none" stroke="#aa92e5" strokeOpacity=".27" strokeWidth="1.5" transform="rotate(-8 264 183)"/>

                                    <g clipPath="url(#leftPortal)">
                                        <path d="M94 47h145v277H94z" fill="url(#futureLeft)"/>
                                        <circle cx="157" cy="121" r="58" fill="#fff" opacity=".2"/>
                                        <path d="M96 242 128 211l19 18 24-60 14 30 20-41 31 55v99H96z" fill="#6879c2" opacity=".65"/>
                                        <path d="m111 237 23-25 13 15 20-52 15 31 19-34 30 41v93H111z" fill="#5367af" opacity=".86"/>
                                        <path d="M126 244h9v38h-9zm27-22h8v60h-8zm29 5h9v55h-9zm24-14h8v69h-8z" fill="#c9dcff" opacity=".82"/>
                                        <path d="M95 270q72-17 144 0v56H95z" fill="url(#water)"/>
                                        <path d="M109 285h116m-100 10h83m-95 9h103" stroke="#edf2ff" strokeOpacity=".58" strokeWidth="2"/>
                                    </g>

                                    <g clipPath="url(#rightPortal)">
                                        <path d="M300 48h145v276H300z" fill="url(#futureRight)"/>
                                        <circle cx="370" cy="111" r="48" fill="#fff4dc" opacity=".66"/>
                                        <path d="m297 229 40-62 28 36 27-55 52 74v104H297z" fill="#9b8dc8" opacity=".76"/>
                                        <path d="m318 226 24-37 14 20 17-28 17 32 20-33 40 49v91H318z" fill="#786eaa" opacity=".77"/>
                                        <path d="M299 252q62-16 145 2v75H299z" fill="#9a9bd0" opacity=".8"/>
                                        <path d="M313 271q57 12 119 0m-107 15q49 12 96 0m-82 16q37 9 70 0" fill="none" stroke="#eeeaff" strokeOpacity=".72" strokeWidth="2"/>
                                    </g>

                                    <path d="M111 53 229 91v206l-118 25z" fill="none" stroke="url(#frame)" strokeWidth="5" strokeLinejoin="round"/>
                                    <path d="m309 91 118-38v269l-118-25z" fill="none" stroke="url(#frame)" strokeWidth="5" strokeLinejoin="round"/>
                                    <path d="m118 61 103 33v190l-103 22zM316 96l104-34v247l-104-23z" fill="none" stroke="#fff" strokeOpacity=".62" strokeWidth="1.5"/>
                                    <path d="m111 322 118-25m80 25 118 25" stroke="#7e68bc" strokeOpacity=".24" strokeWidth="5"/>
                                    <g fill="#fff"><circle cx="72" cy="125" r="2.5" opacity=".9"/><circle cx="457" cy="121" r="3" opacity=".8"/><circle cx="391" cy="28" r="2" opacity=".7"/></g>
                                </svg>
                            </div>
                        </section>

                        <section className="projects-section" id="projects" aria-labelledby="projects-title">
                            <div className="section-heading projects-heading">
                                <div>
                                    <p className="eyebrow">YOUR WORKSPACE</p>
                                    <h2 id="projects-title">Projects</h2>
                                    <p>Choose a project to open its workspace.</p>
                                </div>
                                <label className="search-box">
                                    <span className="search-icon" aria-hidden="true">⌕</span>
                                    <span className="sr-only">Search projects</span>
                                    <input id="project-search" type="search" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search projects" />
                                    {search && <button type="button" className="clear-search" onClick={() => setSearch('')} aria-label="Clear project search">×</button>}
                                </label>
                            </div>

                            {projectsLoading ? (
                                <div className="jira-state" role="status"><span className="loading-indicator" /> Loading Jira projects…</div>
                            ) : projectsError ? (
                                <div className="jira-state jira-error" role="alert"><span>{projectsError}</span><button type="button" className="retry-button" onClick={() => setProjectReloadKey((key) => key + 1)}>Try again</button></div>
                            ) : filteredProjects.length ? (
                                <div className="projects-grid">
                                    {filteredProjects.map((project, index) => (
                                        <article className="project-card" key={project.id}>
                                            <div className="project-card-top">
                                                <div className={`project-icon project-icon-${index % 3}`} aria-hidden="true">{(project.key || project.name || 'J').slice(0, 1)}</div>
                                                <span className="project-key">{project.key}</span>
                                            </div>
                                            <h3>{project.name}</h3>
                                            <p className="project-description">{project.projectTypeKey ? `${project.projectTypeKey} project` : 'Jira project'}</p>
                                            <div className="project-card-bottom">
                                                <span className="issue-count"><span aria-hidden="true">▤</span> Jira project</span>
                                                <button type="button" className="open-button" onClick={() => { setSelectedProject(project); setActiveNav('Projects'); window.scrollTo({ top: 0, behavior: 'smooth' }); }} aria-label={`Open ${project.name} project`}>
                                                    Open project <span aria-hidden="true">→</span>
                                                </button>
                                            </div>
                                        </article>
                                    ))}
                                </div>
                            ) : (
                                <div className="no-results"><span aria-hidden="true">⌕</span><h3>{projects.length ? 'No projects found' : 'No Jira projects available'}</h3><p>{projects.length ? 'Try another project name or Jira key.' : 'No projects were returned for this Jira account.'}</p></div>
                            )}
                        </section>
                    </>
                )}
                <footer className="footer"><span>PARALLEL <i>·</i> Explore what could be.</span><span>Projects are sample data</span></footer>
            </main>
        </div>
    );
}

export default App;
